*{box-sizing:border-box} :root{--ink:#f7f5eb;--muted:#9aaba1;--lime:#c8f05c;--orange:#ff9e56;--panel:rgba(15,27,25,.82)}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#142421;color:var(--ink);font-family:'DM Sans',sans-serif}button{font:inherit;color:inherit}#game-shell{position:relative;width:100vw;height:100dvh;overflow:hidden;background:#76975d}canvas#game{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,transparent 46%,rgba(9,18,18,.18) 100%),linear-gradient(180deg,rgba(8,19,18,.34),transparent 25%,transparent 65%,rgba(8,18,17,.4)}.topbar{position:absolute;z-index:2;top:0;left:0;right:0;height:72px;display:flex;align-items:center;padding:0 36px;background:linear-gradient(180deg,rgba(11,21,20,.78),rgba(11,21,20,.08));gap:26px}.brand{display:flex;align-items:center;gap:10px;min-width:220px}.brand-mark{width:37px;height:37px;background:var(--lime);color:#18211a;display:grid;place-items:center;clip-path:polygon(0 0,100% 0,83% 100%,0 84%);font:900 25px 'Barlow Condensed';font-style:italic}.brand b{font:800 21px 'Barlow Condensed';letter-spacing:1.6px;display:block;line-height:1}.brand small{font-size:8px;letter-spacing:2px;color:#b1c2b5}.match-pill{border:1px solid rgba(255,255,255,.19);border-radius:4px;padding:8px 12px;font-size:9px;letter-spacing:1.2px;font-weight:700;color:#dce7dc}.match-pill i{display:inline-block;width:6px;height:6px;background:var(--lime);border-radius:100%;margin-right:7px;box-shadow:0 0 8px var(--lime)}.top-right{margin-left:auto;display:flex;align-items:center;gap:10px}.ping{display:flex;align-items:end;gap:2px;font-size:8px;color:#aab8ad;margin-right:10px}.ping span{width:3px;background:var(--lime);height:5px;border-radius:2px}.ping span:nth-child(2){height:8px}.ping span:nth-child(3){height:11px;margin-right:5px}.ping b{font-size:10px;color:#f3f5eb;margin-right:2px}.icon-button{width:33px;height:33px;border:1px solid rgba(255,255,255,.2);background:rgba(255,255,255,.07);border-radius:5px;cursor:pointer;font-size:16px}.icon-button:hover{background:rgba(255,255,255,.18)}.hud-top-left{position:absolute;z-index:2;top:91px;left:36px}.phase-label{font:800 12px 'Barlow Condensed';letter-spacing:1.8px;display:flex;align-items:center;gap:8px}.phase-dot{height:8px;width:8px;border-radius:50%;background:var(--lime);box-shadow:0 0 12px var(--lime)}.objective{font-size:10px;margin-top:6px;color:#d4dfd4;text-shadow:0 1px 5px #15211d}.hud-top-right{position:absolute;z-index:2;right:35px;top:90px;display:flex;gap:8px;align-items:flex-start}.alive-card,.elims-card{height:46px;padding:7px 11px;background:var(--panel);border:1px solid rgba(239,245,219,.13);display:flex;align-items:center;gap:9px;min-width:90px;backdrop-filter:blur(8px)}.person-icon,.crosshair-icon{color:var(--lime);font-size:16px}.alive-card strong,.elims-card strong{display:block;font:800 17px 'Barlow Condensed';line-height:16px}.alive-card small,.elims-card small{font-size:7px;letter-spacing:1.1px;color:#a9b5aa}.mini-map{width:145px;background:rgba(14,26,23,.88);border:1px solid rgba(239,245,219,.23);position:relative;margin-left:4px;box-shadow:0 5px 25px #10191455}.mini-map canvas{width:143px;height:143px;display:block}.map-label{height:20px;padding:4px 7px;font:700 8px 'Barlow Condensed';letter-spacing:1px;color:#d8e2d5}.map-label span{float:right;color:var(--lime);font-size:7px}.hud-bottom-left{position:absolute;z-index:2;bottom:28px;left:35px;width:250px}.player-card{display:flex;align-items:center;gap:9px;padding:8px 11px;background:linear-gradient(90deg,rgba(13,25,23,.91),rgba(13,25,23,.52));border-left:2px solid var(--lime)}.avatar{width:30px;height:30px;border-radius:50%;display:grid;place-items:center;background:linear-gradient(140deg,#d9bd77,#64795b);color:#f9edca;font-size:18px;border:1px solid #e6d69d}.player-name b{font:700 11px 'Barlow Condensed';letter-spacing:.8px;display:block}.player-name small{font-size:8px;color:#9daea1;letter-spacing:.8px}.player-name small span{color:var(--lime);padding:0 4px}.net-status{margin-left:auto;font-size:9px;color:var(--lime)}.vitals{padding:9px 10px 0}.vital-row{display:flex;align-items:center;gap:7px;height:15px;margin-bottom:5px}.vital-symbol{width:14px;font-size:13px;text-align:center}.shield-symbol{color:#69d1e8}.health-symbol{color:#b6ed65}.bar-wrap{height:6px;background:rgba(10,15,12,.63);flex:1;transform:skewX(-13deg);overflow:hidden}.bar{height:100%;width:100%;transition:width .2s}.shield-bar{background:#64d2e7}.health-bar{background:#b6ed65}.vital-row b{font:700 10px 'Barlow Condensed';width:21px;text-align:right}.hud-bottom-right{position:absolute;z-index:2;right:35px;bottom:26px;width:310px}.weapon-panel{background:linear-gradient(120deg,rgba(13,25,23,.93),rgba(18,30,27,.73));border:1px solid rgba(233,242,219,.2);border-bottom:2px solid var(--lime);padding:10px 12px 9px;backdrop-filter:blur(9px)}.weapon-info{display:flex;justify-content:space-between;align-items:center}.weapon-info small{color:#c3df75;font-size:7px;letter-spacing:1.3px;font-weight:700;display:block}.weapon-info strong{display:block;font:700 17px 'Barlow Condensed';letter-spacing:.4px}.ammo{display:flex;align-items:baseline;gap:4px}.ammo strong{font:800 24px 'Barlow Condensed'}.ammo span{font-size:11px;color:#a9b6aa}.weapon-art{height:31px;display:flex;align-items:center;justify-content:center}.gun-shape{position:relative;width:110px;height:8px;background:#a5ae98;border-radius:2px;box-shadow:0 2px 0 #51594d}.gun-shape:before{content:'';position:absolute;left:10px;top:-5px;width:59px;height:6px;background:#d1d6ba;border-radius:2px}.gun-shape:after{content:'';position:absolute;left:43px;top:5px;width:9px;height:13px;background:#71796b;transform:skew(-16deg)}.gun-shape i{position:absolute;right:-20px;top:2px;width:24px;height:3px;background:#737e6d}.quickbar{display:flex;gap:5px;margin-top:3px}.slot{height:38px;flex:1;border:1px solid rgba(255,255,255,.23);background:rgba(255,255,255,.06);position:relative;display:flex;align-items:center;justify-content:center;font-size:17px;color:#e5e9d8}.slot.active{border:1px solid var(--lime);background:rgba(200,240,92,.16);box-shadow:inset 0 0 0 1px #c8f05c33}.slot .slot-key{position:absolute;left:4px;top:2px;font-size:7px;color:#a7b3a5}.slot .slot-count{position:absolute;right:4px;bottom:1px;font-size:8px;color:#fff}.center-notice{position:absolute;z-index:3;top:31%;left:50%;transform:translate(-50%,-50%);font:900 clamp(21px,4vw,47px) 'Barlow Condensed';letter-spacing:2px;color:white;text-shadow:0 3px 20px #111;opacity:0;transition:opacity .3s;pointer-events:none;text-align:center}.center-notice.show{opacity:1}.storm-warning{position:absolute;z-index:3;top:22%;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:10px;padding:9px 15px;background:rgba(30,18,24,.87);border:1px solid rgba(255,117,127,.5);opacity:0;transition:opacity .25s}.storm-warning.show{opacity:1}.storm-warning>span{font-size:19px;color:#ff797d}.storm-warning b{font:800 12px 'Barlow Condensed';letter-spacing:1px;display:block}.storm-warning small{font-size:9px;color:#d4b8b8}.feed{position:absolute;z-index:2;top:155px;left:36px;font-size:10px;text-shadow:0 1px 5px #111;max-width:250px}.feed div{margin-bottom:5px;animation:feed-in .25s ease-out}.feed b{color:var(--lime)}@keyframes feed-in{from{transform:translateX(-8px);opacity:0}to{transform:none;opacity:1}}.controls-hint{position:absolute;z-index:2;left:50%;bottom:16px;transform:translateX(-50%);font-size:8px;letter-spacing:.8px;color:#d3d9ce;white-space:nowrap;text-shadow:0 1px 4px #101}.controls-hint span{color:var(--lime);padding:0 6px}.controls-hint kbd{font:700 8px 'DM Sans';padding:3px 4px;border:1px solid #ffffff66;background:#15211cc9;border-radius:2px;color:white;margin:0 1px}.screen{position:absolute;z-index:10;inset:0;display:grid;place-items:center;background:rgba(10,18,17,.58);backdrop-filter:blur(3px);transition:opacity .3s}.screen.hidden{opacity:0;pointer-events:none}.intro-backdrop{position:absolute;inset:0;background:linear-gradient(90deg,rgba(9,19,18,.94) 0%,rgba(9,19,18,.78) 44%,rgba(9,19,18,.1) 100%),linear-gradient(0deg,rgba(11,19,17,.5),transparent 50%)}.intro-content{position:absolute;left:10%;top:50%;transform:translateY(-46%);width:min(440px,44vw)}.season-tag{font-size:9px;letter-spacing:2px;color:var(--lime);font-weight:700;display:flex;align-items:center;gap:8px}.season-tag span{width:7px;height:7px;border-radius:50%;background:var(--lime);box-shadow:0 0 10px var(--lime)}.intro-title{font:900 clamp(62px,8vw,105px)/.8 'Barlow Condensed';letter-spacing:-2px;margin:20px 0 14px;text-shadow:0 4px 20px #14201b}.intro-title em{color:var(--lime);font-style:normal}.intro-content>p{font-size:14px;color:#c2cdc1;margin:20px 0 26px}.intro-meta{display:flex;gap:30px;margin-bottom:28px}.intro-meta>div{display:grid;grid-template-columns:30px auto;grid-template-rows:16px 13px;align-items:center}.meta-icon{grid-row:span 2;color:var(--lime);font-size:21px}.intro-meta b{font:700 11px 'Barlow Condensed';letter-spacing:.8px}.intro-meta small{color:#97a79a;font-size:8px;letter-spacing:.6px}.play-button{height:51px;min-width:220px;background:var(--lime);border:0;color:#192219;display:flex;justify-content:space-between;align-items:center;padding:0 16px 0 20px;cursor:pointer;clip-path:polygon(0 0,100% 0,95% 100%,0 100%);transition:transform .15s,filter .15s}.play-button span{font:900 15px 'Barlow Condensed';letter-spacing:1.6px}.play-button b{font-size:23px}.play-button:hover{filter:brightness(1.1);transform:translateY(-2px)}.intro-foot{font-size:9px;color:#849487;margin-top:18px}.intro-foot span{color:var(--lime);padding:0 5px}.intro-side{position:absolute;right:9%;top:49%;transform:translateY(-50%);width:35vw;max-width:470px;text-align:center}.island-orbit{aspect-ratio:1;position:relative;display:grid;place-items:center}.orbit-ring{position:absolute;border:1px solid rgba(207,239,157,.23);border-radius:50%;transform:rotate(-25deg) scaleY(.48)}.ring-one{inset:8%}.ring-two{inset:0;border-color:rgba(207,239,157,.12);transform:rotate(41deg) scaleY(.54)}.island-disc{width:67%;height:67%;border-radius:50%;background:radial-gradient(circle at 40% 36%,#537953,#2b503e 58%,#183b34 70%,#152a29 71%);box-shadow:0 0 45px #96d9562d,inset 0 0 24px #b5d87722;transform:rotate(-18deg) scaleY(.64);position:relative;overflow:hidden}.island-land{position:absolute;inset:13%;border-radius:43% 53% 46% 52%;background:linear-gradient(135deg,#9bb36a,#678652 50%,#3f7350);clip-path:polygon(20% 5%,48% 0,62% 13%,90% 9%,97% 35%,83% 47%,92% 70%,67% 81%,56% 98%,37% 86%,10% 91%,2% 63%,14% 48%,4% 24%);box-shadow:inset 0 0 10px #dce8a8}.island-land:before{content:'';position:absolute;inset:16%;background:repeating-linear-gradient(45deg,transparent 0 14px,#d2cc8b45 15px 17px);opacity:.7}.island-pin{position:absolute;color:#f2d579;font-size:13px;text-shadow:0 0 9px #ffecab;transform:rotate(18deg)}.pin-a{left:32%;top:30%}.pin-b{left:61%;top:45%}.pin-c{left:46%;top:68%}.orbit-star{position:absolute;color:var(--lime)}.star-one{right:12%;top:22%;font-size:21px}.star-two{left:11%;bottom:20%;font-size:24px;color:#e5c773}.island-caption{display:flex;justify-content:center;gap:11px;align-items:center;margin-top:-3px}.island-caption b{font:700 11px 'Barlow Condensed';letter-spacing:1.7px}.island-caption span{font-size:8px;color:#9cac9d;letter-spacing:1px}.modal{position:relative;text-align:center;background:linear-gradient(145deg,rgba(22,37,33,.98),rgba(13,23,22,.98));border:1px solid #d5e7bb55;padding:38px 44px;width:min(410px,90vw);box-shadow:0 20px 80px #0008}.modal .season-tag{justify-content:center}.modal h2{font:900 44px 'Barlow Condensed';line-height:.95;margin:15px 0 9px}.modal p{font-size:12px;color:#aebcaf;margin:0 0 23px}.modal .play-button{width:100%;margin:0 auto 13px}.text-button{background:none;border:0;color:#9dab9e;text-decoration:underline;font-size:9px;letter-spacing:1px;cursor:pointer}.text-button:hover{color:white}.end-stats{display:flex;justify-content:center;gap:55px;margin:20px 0 25px}.end-stats b{display:block;font:800 28px 'Barlow Condensed';color:var(--lime)}.end-stats small{font-size:8px;letter-spacing:1px;color:#aab8aa}.mobile-controls{display:none}
@media(max-width:750px){.topbar{height:54px;padding:0 14px}.brand{min-width:auto}.brand-mark{width:30px;height:30px;font-size:20px}.brand b{font-size:17px}.brand small{font-size:6px}.match-pill{display:none}.ping{display:none}.hud-top-left{top:65px;left:14px}.hud-top-right{top:63px;right:12px;gap:4px}.alive-card,.elims-card{min-width:62px;padding:5px 7px;height:37px;gap:5px}.alive-card strong,.elims-card strong{font-size:14px}.alive-card small,.elims-card small{font-size:6px}.person-icon,.crosshair-icon{font-size:12px}.mini-map{width:92px;margin-left:0}.mini-map canvas{width:90px;height:90px}.map-label{font-size:7px;height:16px}.map-label span{font-size:6px}.hud-bottom-left{bottom:15px;left:12px;width:170px}.player-card{padding:5px 7px;gap:6px}.avatar{width:25px;height:25px;font-size:14px}.player-name b{font-size:9px}.hud-bottom-right{right:12px;bottom:14px;width:208px}.weapon-panel{padding:7px}.weapon-info strong{font-size:14px}.weapon-info small{font-size:6px}.ammo strong{font-size:19px}.weapon-art{height:23px}.quickbar{gap:3px}.slot{height:31px;font-size:14px}.controls-hint{display:none}.mobile-controls{display:block;position:absolute;z-index:4;inset:0;pointer-events:none}.move-pad{pointer-events:auto;position:absolute;bottom:97px;left:22px;width:116px;height:116px;border-radius:50%;border:1px solid #ffffff40;background:#18231d66;touch-action:none}.pad-thumb{position:absolute;left:35px;top:35px;width:44px;height:44px;border-radius:50%;background:#c8f05c83;border:1px solid #e4ff9d;box-shadow:0 0 15px #b6e95855}.mobile-controls button{pointer-events:auto;position:absolute;border:1px solid #e9f8c685;background:#c8f05cbb;color:#17221a;font:900 12px 'Barlow Condensed';letter-spacing:1px;border-radius:50%;width:64px;height:64px;right:20px;bottom:125px;touch-action:none}.mobile-controls #mobile-pickup{width:46px;height:46px;right:93px;bottom:95px;background:#12211dcc;color:white;border-color:#fff8;font-size:9px}.intro-content{left:7%;top:47%;width:85%;transform:translateY(-40%)}.intro-title{font-size:clamp(58px,15vw,86px);margin-top:16px}.intro-content>p{font-size:12px}.intro-side{right:-13%;top:22%;width:57vw;opacity:.5}.intro-meta{gap:18px}.intro-meta b{font-size:10px}.play-button{height:47px;min-width:190px}.intro-foot{font-size:8px}.feed{top:112px;left:14px;font-size:9px}.phase-label{font-size:10px}.objective{font-size:8px;max-width:140px}.storm-warning{top:27%;padding:7px 10px}.storm-warning b{font-size:10px}.storm-warning small{font-size:8px}.center-notice{top:38%}.island-caption{font-size:9px;flex-direction:column;gap:3px}.modal{padding:32px 27px}}
@media(max-height:540px){.intro-side{width:28vw}.intro-content{top:52%}.intro-title{font-size:58px}.intro-content>p{margin:11px 0 14px}.intro-meta{margin-bottom:14px}.hud-bottom-left,.hud-bottom-right{bottom:10px}.mini-map{width:112px}.mini-map canvas{width:110px;height:110px}}

(() => {
'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),mini=document.getElementById('minimap'),mctx=mini.getContext('2d');
const ui={intro:document.getElementById('intro-screen'),pause:document.getElementById('pause-screen'),end:document.getElementById('end-screen'),alive:document.getElementById('alive-count'),elims:document.getElementById('elim-count'),health:document.getElementById('health-value'),shield:document.getElementById('shield-value'),healthBar:document.getElementById('health-bar'),shieldBar:document.getElementById('shield-bar'),ammo:document.getElementById('ammo-now'),reserve:document.getElementById('ammo-reserve'),weapon:document.getElementById('weapon-name'),rarity:document.getElementById('weapon-rarity'),phase:document.getElementById('phase-text'),objective:document.getElementById('objective'),warning:document.getElementById('storm-warning'),notice:document.getElementById('center-notice'),feed:document.getElementById('feed'),quickbar:document.getElementById('quickbar')};
const W=2400,H=2400,TAU=Math.PI*2,rand=(a,b)=>a+Math.random()*(b-a),clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
let dpr=1,cw=innerWidth,ch=innerHeight,cam={x:1200,y:1200},state='lobby',last=0,keys={},mouse={x:cw/2,y:ch/2,down:false},touchMove={x:0,y:0},audio=null,soundOn=true,zone={x:1200,y:1200,r:1050,from:1050,to:260,time:0,duration:190,stage:0};
let player,bots=[],bullets=[],loot=[],trees=[],rocks=[],builds=[],particles=[],deco=[],islandFeatures=[],elapsed=0,alive=15,elims=0,selected=0,noticeTimer=0,botNames=['Mossy','Hex','Sundown','Pinecone','Juno','Latch','Wicket','Rook','Sable','Clover','Mica','Dusty','Nova','Pip'];
const weapons=[{name:'Trailblazer AR',type:'RIFLE',damage:22,rate:.17,speed:13,mag:24,reserve:96,spread:.055,color:'#b9dc72',rarity:'COMMON'},{name:'Switchback SMG',type:'SMG',damage:12,rate:.09,speed:14,mag:32,reserve:128,spread:.12,color:'#79d7c3',rarity:'UNCOMMON'},{name:'Ridgeback Scattergun',type:'SHOTGUN',damage:13,rate:.68,speed:11,mag:6,reserve:30,spread:.36,pellets:7,color:'#e6ab65',rarity:'UNCOMMON'},{name:'Scout Sidearm',type:'SIDEARM',damage:18,rate:.3,speed:12,mag:12,reserve:72,spread:.07,color:'#d7d4be',rarity:'COMMON'}];
const sites=[{name:'PINEWATCH',x:430,y:520,kind:'village'},{name:'SUNSPOT STATION',x:1190,y:410,kind:'depot'},{name:'MOSSY MILE',x:1920,y:620,kind:'village'},{name:'CINDER YARD',x:510,y:1250,kind:'yard'},{name:'RUSTLEAF ROW',x:1200,y:1200,kind:'village'},{name:'DRIFTWOOD DOCKS',x:1950,y:1330,kind:'dock'},{name:'WINDMILL HOLLOW',x:430,y:2020,kind:'hill'},{name:'CAMP WAYFARER',x:1240,y:1990,kind:'camp'},{name:'GOLDEN GROVE',x:1950,y:2050,kind:'village'}];
function resize(){dpr=Math.min(devicePixelRatio||1,2);cw=innerWidth;ch=innerHeight;canvas.width=Math.floor(cw*dpr);canvas.height=Math.floor(ch*dpr);canvas.style.width=cw+'px';canvas.style.height=ch+'px';ctx.setTransform(dpr,0,0,dpr,0,0)}
addEventListener('resize',resize);resize();
function makeAudio(){if(!audio){audio=new(window.AudioContext||window.webkitAudioContext)();}if(audio.state==='suspended')audio.resume()}
function tone(freq,dur,type='sine',vol=.05,endFreq=null){if(!soundOn)return;makeAudio();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);if(endFreq)o.frequency.exponentialRampToValueAtTime(endFreq,audio.currentTime+dur);g.gain.setValueAtTime(vol,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur)}
function shotSound(weapon){if(!soundOn)return;makeAudio();const dur=weapon.type==='SHOTGUN'?.21:.12,buffer=audio.createBuffer(1,Math.floor(audio.sampleRate*dur),audio.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*(1-i/data.length);const src=audio.createBufferSource(),filter=audio.createBiquadFilter(),gain=audio.createGain();src.buffer=buffer;filter.type='lowpass';filter.frequency.value=weapon.type==='SHOTGUN'?850:1900;gain.gain.setValueAtTime(.14,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);src.connect(filter);filter.connect(gain);gain.connect(audio.destination);src.start();tone(weapon.type==='SHOTGUN'?80:140,.09,'triangle',.04,45)}
function say(text, duration=2){ui.notice.textContent=text;ui.notice.classList.add('show');noticeTimer=duration}
function feed(text){const item=document.createElement('div');item.innerHTML=text;ui.feed.prepend(item);while(ui.feed.children.length>4)ui.feed.lastChild.remove();setTimeout(()=>item.remove(),5500)}
function randSite(){return sites[Math.floor(Math.random()*sites.length)]}
function createWorld(){trees=[];rocks=[];builds=[];deco=[];islandFeatures=[];
 for(const site of sites){const rr=site.kind==='village'?155:site.kind==='yard'?130:site.kind==='dock'?120:100;for(let i=0;i<(site.kind==='village'?9:5);i++){const x=site.x+rand(-rr,rr),y=site.y+rand(-rr,rr),w=rand(35,58),h=rand(31,52);builds.push({x,y,w,h,roof:['#ad7250','#b78550','#87965a','#9a6652'][Math.floor(rand(0,4))],wall:['#d4c393','#c7b184','#aeb58b'][Math.floor(rand(0,3))],rotation:rand(-.05,.05),site:site.name})}}
 for(let i=0;i<520;i++){const x=rand(45,W-45),y=rand(45,H-45);if(sites.some(s=>Math.hypot(x-s.x,y-s.y)<180))continue;trees.push({x,y,r:rand(12,23),tone:Math.floor(rand(0,4)),kind:Math.random()<.78?'pine':'round',seed:rand(0,100)})}
 for(let i=0;i<170;i++)rocks.push({x:rand(30,W-30),y:rand(30,H-30),r:rand(7,20),seed:rand(0,10)});
 for(let i=0;i<250;i++)deco.push({x:rand(0,W),y:rand(0,H),size:rand(2,7),kind:Math.random()<.5?'flower':'grass',hue:rand(0,1)});
 islandFeatures=[{x:810,y:880,r:110},{x:1630,y:930,r:95},{x:870,y:1740,r:120},{x:1660,y:1710,r:90}];
}
function newPlayer(){return{x:1200,y:1200,angle:0,r:13,hp:100,shield:50,weapon:0,ammo:24,reserve:96,reload:0,shoot:0,medkits:1,materials:90,alive:true,invuln:0}}
function makeLoot(x,y,type){loot.push({x,y,type,phase:rand(0,TAU),amount:type==='ammo'?24:type==='heal'?1:type==='material'?25:1})}
function spawn(){createWorld();player=newPlayer();bots=[];bullets=[];loot=[];particles=[];elapsed=0;elims=0;alive=15;selected=0;zone={x:1200,y:1200,r:1050,from:1050,to:260,time:0,duration:190,stage:0};for(let i=0;i<14;i++){let p;do{p={x:rand(180,W-180),y:rand(180,H-180)}}while(dist(p,{x:1200,y:1200})<150);bots.push({...p,r:12,hp:100,shield:rand(0,45),weapon:weapons[Math.floor(rand(0,3))],cool:rand(.3,1.3),angle:rand(0,TAU),target:null,name:botNames[i],alive:true,think:0,roam:rand(0,TAU),color:['#d88b62','#88a9a0','#cdba6d','#9e8bc5','#d57d79'][i%5]});if(i<9)makeLoot(p.x+rand(-80,80),p.y+rand(-80,80),['ammo','weapon','heal','material'][i%4])}for(let i=0;i<40;i++){const x=rand(100,W-100),y=rand(100,H-100);makeLoot(x,y,['ammo','weapon','heal','material'][Math.floor(rand(0,4))])}cam.x=player.x;cam.y=player.y;ui.feed.innerHTML='';ui.intro.classList.add('hidden');ui.pause.classList.add('hidden');ui.end.classList.add('hidden');state='playing';tone(440,.12,'sine',.04,660);setTimeout(()=>say('GOOD LUCK OUT THERE',2),300);syncUI()}

