function startReload(){if(!player||player.reload||player.ammo>=weapons[player.weapon].mag||player.reserve<=0)return;player.reload=player.weapon===2?1.35:1.55;tone(360,.07,'square',.025,250)}
function doShoot(owner,angle,weapon,fromPlayer=true){const count=weapon.pellets||1;for(let i=0;i<count;i++){const a=angle+rand(-weapon.spread,weapon.spread);bullets.push({x:owner.x+Math.cos(a)*18,y:owner.y+Math.sin(a)*18,vx:Math.cos(a)*weapon.speed,vy:Math.sin(a)*weapon.speed,life:.8,damage:weapon.damage,fromPlayer,owner,weapon})}if(fromPlayer){player.ammo--;player.shoot=weapon.rate;shotSound(weapon);if(player.ammo===0)startReload()}else tone(100,.06,'triangle',.012,68)}
function fire(){if(state!=='playing'||!player.alive||player.reload||player.shoot>0)return;const w=weapons[player.weapon];if(player.ammo<=0){startReload();return}const wx=mouse.x-cw/2+cam.x,wy=mouse.y-ch/2+cam.y;player.angle=Math.atan2(wy-player.y,wx-player.x);doShoot(player,player.angle,w,true)}
function damage(target,amount,attacker){if(!target.alive)return;let rest=amount;if(target.shield>0){const used=Math.min(target.shield,rest);target.shield-=used;rest-=used}target.hp=Math.max(0,target.hp-rest);for(let i=0;i<5;i++)particles.push({x:target.x,y:target.y,vx:rand(-2,2),vy:rand(-2,2),life:.35,color:target===player?'#69d3e6':'#f0ca7a'});if(target.hp<=0){target.alive=false;alive--;if(target===player){endGame(false);return}if(attacker===player){elims++;feed(`<b>ELIMINATION</b> — ${target.name}`);tone(550,.11,'sine',.04,880);const choices=['ammo','material','heal'];makeLoot(target.x,target.y,choices[Math.floor(Math.random()*choices.length)]);if(Math.random()<.65)makeLoot(target.x+14,target.y-7,'weapon')}else feed(`${target.name} was eliminated`);syncUI();if(alive<=1&&player.alive)endGame(true)}}
function collect(){if(!player)return;const item=loot.find(l=>Math.hypot(l.x-player.x,l.y-player.y)<45);if(!item){say('NOTHING TO PICK UP',.8);return}if(item.type==='weapon'){let idx=Math.floor(rand(0,3));if(idx===player.weapon)idx=(idx+1)%4;player.weapon=idx;player.ammo=weapons[idx].mag;player.reserve+=24;say(weapons[idx].name.toUpperCase(),1);tone(620,.12,'sine',.04,880)}else if(item.type==='ammo'){player.reserve+=item.amount;say(`+${item.amount} AMMO`,.8);tone(720,.08)}else if(item.type==='heal'){player.medkits=Math.min(3,player.medkits+1);say('MED SPRAY ADDED',.8);tone(620,.1)}else{player.materials+=item.amount;say(`+${item.amount} BUILD MATERIAL`,.8);tone(490,.08)}loot.splice(loot.indexOf(item),1);syncUI()}
function useHeal(){if(!player||player.medkits<=0||player.hp>=100)return;player.medkits--;player.hp=Math.min(100,player.hp+45);say('MED SPRAY +45',1);tone(440,.2,'sine',.06,760);syncUI()}
function buildWall(){if(!player||player.materials<15)return;player.materials-=15;const x=player.x+Math.cos(player.angle)*42,y=player.y+Math.sin(player.angle)*42;builds.push({x,y,w:42,h:9,roof:'#b5a77c',wall:'#c8b881',rotation:player.angle+Math.PI/2,playerMade:true,hp:100});tone(190,.11,'triangle',.04,120);say('WALL BUILT',.7)}
function syncUI(){if(!player)return;ui.alive.textContent=alive;ui.elims.textContent=elims;ui.health.textContent=Math.ceil(player.hp);ui.shield.textContent=Math.ceil(player.shield);ui.healthBar.style.width=player.hp+'%';ui.shieldBar.style.width=(player.shield/100*100)+'%';ui.ammo.textContent=player.ammo;ui.reserve.textContent=player.reserve;const w=weapons[player.weapon];ui.weapon.textContent=w.name;ui.rarity.textContent=`${w.rarity} • ${w.type}`;ui.rarity.style.color=w.color;const symbols=['⚒','▧','✚','◈','◉'];ui.quickbar.innerHTML=symbols.map((s,i)=>`<div class="slot ${i===selected?'active':''}" data-slot="${i}"><span class="slot-key">${i+1}</span>${s}<span class="slot-count">${i===0?player.ammo:i===1?player.reserve:i===2?player.medkits:i===3?player.materials:''}</span></div>`).join('');ui.quickbar.querySelectorAll('.slot').forEach(el=>el.addEventListener('click',()=>selectSlot(+el.dataset.slot)))}
function selectSlot(n){selected=n;if(n<4&&n!==2){if(n<weapons.length){player.weapon=n;player.ammo=Math.min(player.ammo,weapons[n].mag);player.reserve=Math.max(player.reserve,24)}}else if(n===2)useHeal();syncUI()}
function update(dt){if(state!=='playing')return;elapsed+=dt;if(noticeTimer>0&&(noticeTimer-=dt)<=0)ui.notice.classList.remove('show');player.shoot=Math.max(0,player.shoot-dt);player.invuln=Math.max(0,player.invuln-dt);if(player.reload>0){player.reload-=dt;if(player.reload<=0){const w=weapons[player.weapon],take=Math.min(w.mag-player.ammo,player.reserve);player.ammo+=take;player.reserve-=take;tone(520,.07,'square',.025,700);syncUI()}}
 const speed=player.materials>=0?205:180;let dx=(keys.KeyD?1:0)-(keys.KeyA?1:0)+touchMove.x,dy=(keys.KeyS?1:0)-(keys.KeyW?1:0)+touchMove.y;const mag=Math.hypot(dx,dy);if(mag>1){dx/=mag;dy/=mag}player.x=clamp(player.x+dx*speed*dt,20,W-20);player.y=clamp(player.y+dy*speed*dt,20,H-20);player.angle=Math.atan2(mouse.y-ch/2+cam.y-player.y,mouse.x-cw/2+cam.x-player.x);if(mouse.down)fire();
 cam.x+=(player.x-cam.x)*Math.min(1,dt*7);cam.y+=(player.y-cam.y)*Math.min(1,dt*7);
 zone.time+=dt;if(zone.time>zone.duration){zone.time=0;zone.stage++;zone.from=zone.r;zone.to=Math.max(145,zone.r*.69);const a=rand(0,TAU),offset=rand(0,zone.r*.22);zone.x=clamp(zone.x+Math.cos(a)*offset,zone.to,W-zone.to);zone.y=clamp(zone.y+Math.sin(a)*offset,zone.to,H-zone.to);say('SAFE ZONE SHRINKING',2);ui.warning.classList.add('show');setTimeout(()=>ui.warning.classList.remove('show'),3000)}zone.r=zone.from+(zone.to-zone.from)*Math.min(1,zone.time/zone.duration);const outside=dist(player,zone)>zone.r;if(outside){player.hp-=dt*(zone.stage>2?9:5);if(Math.random()<dt*2)tone(70,.05,'sawtooth',.012,45);if(player.hp<=0)damage(player,100, null)}if(elapsed<12){ui.phase.textContent='LOOT UP';ui.objective.textContent='Gear up before the rift starts closing.'}else{ui.phase.textContent=`RIFT ${Math.min(zone.stage+1,5)} • ${Math.max(0,Math.ceil(zone.duration-zone.time))}s`;ui.objective.textContent=outside?'Get back inside the safe zone!':'Stay sharp. The rift is getting smaller.'}
 for(const b of bots){if(!b.alive)continue;b.cool-=dt;b.think-=dt;if(b.think<=0){b.think=rand(.3,.8);b.roam+=rand(-1.5,1.5);if(dist(b,player)<560)b.target=player;else b.target=null}let tx=b.target?b.target.x:b.x+Math.cos(b.roam)*70,ty=b.target?b.target.y:b.y+Math.sin(b.roam)*70;const dx=tx-b.x,dy=ty-b.y,d=Math.hypot(dx,dy);b.angle=Math.atan2(dy,dx);if(b.target&&d<430){const strafe=Math.sin(elapsed*2+b.y)*.45;b.x+=(-Math.cos(b.angle)*.25+Math.cos(b.angle+Math.PI/2)*strafe)*95*dt;b.y+=(-Math.sin(b.angle)*.25+Math.sin(b.angle+Math.PI/2)*strafe)*95*dt;if(b.cool<=0){doShoot(b,b.angle,b.weapon,false);b.cool=b.weapon.rate*rand(4,8)}}else if(d>22){b.x+=Math.cos(b.angle)*67*dt;b.y+=Math.sin(b.angle)*67*dt}b.x=clamp(b.x,20,W-20);b.y=clamp(b.y,20,H-20);if(dist(b,zone)>zone.r)b.hp-=dt*4;if(b.hp<=0)damage(b,200,null)}
 for(let i=bullets.length-1;i>=0;i--){const q=bullets[i];q.x+=q.vx; q.y+=q.vy;q.life-=dt;if(q.life<=0||q.x<0||q.y<0||q.x>W||q.y>H){bullets.splice(i,1);continue}if(q.fromPlayer){const b=bots.find(b=>b.alive&&Math.hypot(q.x-b.x,q.y-b.y)<b.r+4);if(b){damage(b,q.damage,player);bullets.splice(i,1);continue}}else if(player.alive&&Math.hypot(q.x-player.x,q.y-player.y)<player.r+4){damage(player,q.damage,q.owner);bullets.splice(i,1)}}
