function drawLoot(){for(const l of loot){l.phase+=.025;const yy=Math.sin(l.phase)*3;ctx.fillStyle='rgba(20,30,22,.24)';ctx.beginPath();ctx.ellipse(l.x,l.y+8,11,5,0,0,TAU);ctx.fill();ctx.save();ctx.translate(l.x,l.y+yy);ctx.rotate(Math.PI/4);const color=l.type==='weapon'?'#f0b968':l.type==='heal'?'#f48383':l.type==='material'?'#b8a47a':'#c8f05c';ctx.shadowColor=color;ctx.shadowBlur=10;ctx.fillStyle=color;ctx.fillRect(-7,-7,14,14);ctx.shadowBlur=0;ctx.rotate(-Math.PI/4);ctx.fillStyle='#28362d';ctx.font='bold 10px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(l.type==='weapon'?'⌁':l.type==='heal'?'✚':l.type==='material'?'▤':'•',0,0);ctx.restore()}}
function drawCharacter(c,isPlayer){ctx.save();ctx.translate(c.x,c.y);ctx.rotate(c.angle);ctx.fillStyle='rgba(27,39,29,.32)';ctx.beginPath();ctx.ellipse(1,7,14,9,0,0,TAU);ctx.fill();ctx.fillStyle=isPlayer?'#d1b574':c.color;ctx.beginPath();ctx.ellipse(0,0,12,10,0,0,TAU);ctx.fill();ctx.fillStyle=isPlayer?'#536f59':'#334941';ctx.beginPath();ctx.ellipse(-1,0,7,8,0,0,TAU);ctx.fill();ctx.fillStyle=isPlayer?'#d9c996':'#e5c49c';ctx.beginPath();ctx.arc(4,-2,5,0,TAU);ctx.fill();ctx.fillStyle='#323b32';ctx.fillRect(6,-2,17,4);ctx.fillStyle='#88947b';ctx.fillRect(12,-1,8,2);ctx.restore();if(c.shield>0){ctx.strokeStyle=isPlayer?'rgba(112,215,239,.8)':'rgba(220,227,211,.48)';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(c.x,c.y,15,-.4,Math.PI*1.6);ctx.stroke()}if(!isPlayer&&c.target){ctx.fillStyle='#15231c';ctx.fillRect(c.x-14,c.y-20,28,3);ctx.fillStyle='#f17e6e';ctx.fillRect(c.x-14,c.y-20,28*c.hp/100,3)}}
function drawStorm(){ctx.save();ctx.fillStyle='rgba(133,75,151,.21)';ctx.beginPath();ctx.rect(-100,-100,W+200,H+200);ctx.arc(zone.x,zone.y,zone.r,0,TAU,true);ctx.fill('evenodd');ctx.beginPath();ctx.arc(zone.x,zone.y,zone.r,0,TAU);ctx.strokeStyle='rgba(209,157,235,.72)';ctx.lineWidth=5;ctx.setLineDash([11,9]);ctx.stroke();ctx.setLineDash([]);ctx.restore()}
function drawMinimap(){const w=mini.width,h=mini.height,s=w/W;mctx.clearRect(0,0,w,h);mctx.fillStyle='#829d69';mctx.fillRect(0,0,w,h);mctx.fillStyle='#c2b783';for(const site of sites){mctx.beginPath();mctx.arc(site.x*s,site.y*s,site.kind==='village'?10:7,0,TAU);mctx.fill()}mctx.strokeStyle='#c8ba8a';mctx.lineWidth=2;mctx.beginPath();mctx.moveTo(430*s,520*s);for(const p of [[1190,410],[1920,620],[1200,1200],[1950,1330],[1240,1990],[1950,2050]])mctx.lineTo(p[0]*s,p[1]*s);mctx.stroke();mctx.fillStyle='rgba(153,101,171,.32)';mctx.beginPath();mctx.rect(0,0,w,h);mctx.arc(zone.x*s,zone.y*s,zone.r*s,0,TAU,true);mctx.fill('evenodd');mctx.strokeStyle='#ddc5f0';mctx.lineWidth=1.5;mctx.beginPath();mctx.arc(zone.x*s,zone.y*s,zone.r*s,0,TAU);mctx.stroke();for(const b of bots){if(b.alive){mctx.fillStyle='#e7786d';mctx.beginPath();mctx.arc(b.x*s,b.y*s,2.1,0,TAU);mctx.fill()}}if(player){mctx.fillStyle='#e6ff8b';mctx.beginPath();mctx.arc(player.x*s,player.y*s,3.8,0,TAU);mctx.fill();mctx.strokeStyle='#f6ffd9';mctx.lineWidth=1;mctx.stroke()}}
function draw(){if(!player)return;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,cw,ch);ctx.save();ctx.translate(cw/2-cam.x,ch/2-cam.y);drawGround();drawDecor();drawBuildings();drawLoot();drawTrees();drawSiteNames();drawStorm();for(const b of bullets){ctx.fillStyle=b.fromPlayer?'#fff5b0':'#ffb68a';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=7;ctx.beginPath();ctx.arc(b.x,b.y,3,0,TAU);ctx.fill();ctx.shadowBlur=0}for(const p of particles){ctx.globalAlpha=Math.max(0,p.life/.35);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,3,0,TAU);ctx.fill()}ctx.globalAlpha=1;for(const b of bots)if(b.alive)drawCharacter(b,false);if(player.alive)drawCharacter(player,true);ctx.restore();drawMinimap();drawReticle()}
function drawReticle(){if(state!=='playing')return;ctx.save();ctx.strokeStyle='rgba(250,255,229,.92)';ctx.lineWidth=1.2;ctx.beginPath();ctx.arc(mouse.x,mouse.y,7,0,TAU);ctx.moveTo(mouse.x-12,mouse.y);ctx.lineTo(mouse.x-5,mouse.y);ctx.moveTo(mouse.x+5,mouse.y);ctx.lineTo(mouse.x+12,mouse.y);ctx.moveTo(mouse.x,mouse.y-12);ctx.lineTo(mouse.x,mouse.y-5);ctx.moveTo(mouse.x,mouse.y+5);ctx.lineTo(mouse.x,mouse.y+12);ctx.stroke();ctx.restore()}

